css:
.aha-footer-banner{
  --aha-reveal-duration:calc(var(--aha-motion-slow) + var(--aha-motion-mid));
  container:aha-footer-banner / inline-size;
  --aha-footer-banner-surface:var(--aha-vivid-pink-100);
  --aha-footer-banner-ink:var(--aha-text-inverse);
  --aha-footer-banner-cta-bg:var(--aha-white);
  --aha-footer-banner-cta-bg-hover:var(--aha-white);
  --aha-footer-banner-cta-bg-press:var(--aha-white);
  --aha-footer-banner-cta-text:var(--aha-color-primary);
  --aha-footer-banner-focus:var(--aha-white);
  --aha-footer-banner-focus-gap:var(--aha-vivid-pink-100);
  font-family:var(--aha-font-product);
  background:var(--aha-white);
}
.aha-footer-banner aha-button{--aha-button-primary-bg:var(--aha-footer-banner-cta-bg);--aha-button-primary-bg-hover:var(--aha-footer-banner-cta-bg-hover);--aha-button-primary-bg-press:var(--aha-footer-banner-cta-bg-press);--aha-button-primary-text:var(--aha-footer-banner-cta-text);--aha-button-focus-ring:var(--aha-footer-banner-focus);--aha-button-focus-gap:var(--aha-footer-banner-focus-gap)}
.aha-footer-banner__inner{padding:var(--aha-space-96) var(--aha-space-64)}
.aha-footer-banner *{box-sizing:border-box}
:where(.aha-footer-banner) h2,:where(.aha-footer-banner) p{margin:0}
.aha-footer-banner__card{
  position:relative;isolation:isolate;overflow:hidden;
  display:flex;flex-direction:column;align-items:center;
  max-width:1280px;margin:0 auto;
  padding:var(--aha-space-64) var(--aha-space-0);
  border-radius:var(--aha-radius-xl);
  background:var(--aha-footer-banner-surface);
}
.aha-footer-banner__splash{display:block;position:absolute;inset:0;z-index:-1;overflow:hidden;container-type:size;pointer-events:none;border-radius:inherit;--aha-footer-banner-splash-across:.5;--aha-footer-banner-splash-width:calc(4.5*min(100cqw,100cqh)*sqrt(max(1,tan(atan2(100cqw,100cqh))*9/16,9/16/tan(atan2(100cqw,100cqh)))))}
.aha-footer-banner__splash-icon{position:absolute;display:block;max-width:none;height:auto;width:var(--aha-footer-banner-splash-width);left:calc(var(--aha-footer-banner-splash-across)*100cqw - var(--aha-footer-banner-splash-width)*0.516209);top:calc(55cqh - var(--aha-footer-banner-splash-width)*0.418953)}
.aha-footer-banner__title{
  width:100%;max-width:720px;margin-bottom:var(--aha-space-24);
  font-size:var(--aha-size-h2);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);
  text-align:center;color:var(--aha-footer-banner-ink);
}
.aha-footer-banner__text{
  width:100%;max-width:720px;margin-bottom:var(--aha-space-24);
  font-size:var(--aha-size-xl);font-weight:var(--aha-weight-regular);line-height:var(--aha-line-height-body);
  text-align:center;color:var(--aha-footer-banner-ink);
}
@container aha-footer-banner (max-width:991px){
  .aha-footer-banner__card{padding:var(--aha-space-32) var(--aha-space-64)}
  .aha-footer-banner__title{font-size:var(--aha-size-h3)}
}
@container aha-footer-banner (max-width:479px){
  .aha-footer-banner__inner{padding-left:var(--aha-space-32);padding-right:var(--aha-space-32)}
  .aha-footer-banner__card{padding-left:var(--aha-space-32);padding-right:var(--aha-space-32)}
}
.aha-footer-banner--reveal.is-armed .aha-footer-banner__card{opacity:0}
.aha-footer-banner--reveal.is-armed .aha-footer-banner__title{opacity:0;transform:translateY(10%)}
.aha-footer-banner--reveal.is-revealed .aha-footer-banner__title{opacity:1;transform:none;transition:opacity var(--aha-reveal-duration) var(--aha-ease-out),transform var(--aha-reveal-duration) var(--aha-ease-out)}
.aha-footer-banner--reveal.is-revealed .aha-footer-banner__card{opacity:1;transition:opacity var(--aha-reveal-duration) var(--aha-ease-out) var(--aha-motion-slow)}
@media (prefers-reduced-motion:reduce){
  .aha-footer-banner--reveal.is-armed .aha-footer-banner__card,
  .aha-footer-banner--reveal.is-armed .aha-footer-banner__title{opacity:1;transform:none}
}
